import Vue from 'vue';
import Router from 'vue-router';
import Login from './components/login.vue';
import Register from './components/register.vue';
import Home from './components/Home.vue';
Vue.use(Router);
export default new Router({
  routes: [{
    path: '/',
    redirect: '/login'
  }, {
    path: '/login',
    component: Login
  }, {
    path: '/register',
    component: Register
  }, {
    path: '/home',
    component: Home
  }]
});
